def _sha(value: Any) -> str:
    return hashlib.sha256(canonical_json(value).encode()).hexdigest()

def _hash64(value: str, code: str) -> str:
    if len(value) != 64 or any(ch not in "0123456789abcdef" for ch in value):
        raise FailClosed(code)
    return value

def _amendment_d_sha256() -> str:
    configured=os.environ.get("P5_AMENDMENT_D_SHA256",AMENDMENT_D_SHA256)
    if configured!=AMENDMENT_D_SHA256: raise FailClosed("AMENDMENT_D_HASH_DRIFT")
    return _hash64(configured,"AMENDMENT_D_HASH_NOT_PINNED")

def _expected_amendment_hash(amendment_id: str) -> str:
    return {"A": AMENDMENT_A_SHA256, "B": AMENDMENT_B_SHA256,
            "C": AMENDMENT_C_SHA256, "D": _amendment_d_sha256()}[amendment_id]

def _owner_key() -> bytes:
    path = os.environ.get("P5_OWNER_ED25519_PUBLIC_KEY_FILE", "")
    if not path or not Path(path).is_file():
        raise FailClosed("OWNER_PUBLIC_KEY_NOT_CONFIGURED")
    raw = Path(path).read_bytes()
    if len(raw) != 32:
        raise FailClosed("OWNER_PUBLIC_KEY_INVALID")
    return raw

def _owner_uid() -> int:
    return int(os.environ.get("P5_OWNER_PEER_UID", "-1"))

class AuthorityStore:
    def __init__(self, db_path: Path):
        self.db_path = db_path

    def _open(self):
        con = apsw.Connection(str(self.db_path)); con.set_busy_timeout(2000)
        con.execute("PRAGMA foreign_keys=ON")
        return con

    def proposal(self, payload: dict[str, Any], ctx: DaemonContext) -> dict[str, Any]:
        ctx.validate(); bindings = FrozenBindings(**payload["bindings"]).validate()
        proposal_id = str(payload["proposal_id"]); binding_json = canonical_json(vars(bindings))
        resource_hash = resource_policy_sha256(bindings.resource_scope) if bindings.wave_id is not None else None
        con = self._open()
        try:
            con.execute("BEGIN IMMEDIATE")
            con.execute("INSERT INTO authority_proposals(proposal_id,family_id,run_id,run_class,binding_sha256,binding_json,producer_session_id,expires_at,created_at,resource_policy_sha256) VALUES(?,?,?,?,?,?,?,?,?,?)", (proposal_id,bindings.family_id,bindings.run_id,bindings.run_class,bindings.digest,binding_json,ctx.session_id,str(payload["expires_at"]),ctx.recorded_at,resource_hash))
            con.execute("INSERT INTO authority_transitions(proposal_id,from_state,to_state,daemon_recorded_at,daemon_ledger_sequence,immutable_session_id,authenticated_peer_uid,event_sha256,resource_policy_sha256) VALUES(?,?,?,?,?,?,?,?,?)", (proposal_id,"NONE","PROPOSED",ctx.recorded_at,ctx.ledger_sequence,ctx.session_id,ctx.peer_uid,_sha({"p":proposal_id,"to":"PROPOSED","seq":ctx.ledger_sequence}),resource_hash))
            con.execute("COMMIT")
        except BaseException:
            if not con.getautocommit(): con.execute("ROLLBACK")
            raise
        finally: con.close()
        return {"status":"PASS","proposal_id":proposal_id,"state":"PROPOSED","binding_sha256":bindings.digest}

    def transition(self, proposal_id: str, target: str, ctx: DaemonContext, observed_binding_sha256: str|None=None) -> dict[str, Any]:
        ctx.validate(); con = self._open()
        try:
            con.execute("BEGIN IMMEDIATE")
            row = con.execute("SELECT binding_sha256,producer_session_id,expires_at,resource_policy_sha256 FROM authority_proposals WHERE proposal_id=?",(proposal_id,)).fetchone()

"""P5 PC7 authority/amendment/trial runtime (engineering layer).

The daemon supplies ``peer_uid``, append-only sequence and canonical time.
Producer timestamps and payload role strings are never authorization inputs.
This module has no Research Memory write path; production persistence is the
separate, audited schema migration.
"""
from __future__ import annotations

from dataclasses import dataclass, field
from datetime import datetime, timezone
import hashlib
import json
from typing import Any, Callable


STATES = ("PROPOSED", "PRECONDITIONS_PASS", "HUMAN_OWNER_SIGNED", "APPLIED")
RUN_CLASSES = {"STATISTICAL_TRIAL", "SYNTHETIC_TEST"}

RESOURCE_POLICY_TYPE = "WAVE1_CUMULATIVE_ACTIVE_WALL_TIME_V1"
RESOURCE_POLICY_KEYS = {
    "policy_type", "wall_time_expiry_seconds", "clock", "starts_at",
    "accumulation", "checkpoint_semantics", "on_exhaustion",
    "scientific_early_stop", "candidate_count", "decision_basis",
}
RESOURCE_DECISION_BASIS_KEYS = {
    "source", "benchmark_sha256", "real_p5_labels_read_before_choice",
}


class AuthorityError(RuntimeError):
    pass


class AuthorizationDenied(AuthorityError):
    pass


class BindingMismatch(AuthorityError):
    pass


def canonical_json(value: Any) -> bytes:
    return json.dumps(value, ensure_ascii=False, sort_keys=True,
                      separators=(",", ":"), allow_nan=False).encode("utf-8")


def sha256(value: bytes) -> str:
    return hashlib.sha256(value).hexdigest()


def parse_utc(value: str) -> datetime:
    if not isinstance(value, str) or not value.endswith("Z"):
        raise AuthorityError("daemon time must be RFC3339 UTC")
    parsed = datetime.fromisoformat(value[:-1] + "+00:00")
    if parsed.utcoffset() != timezone.utc.utcoffset(parsed):
        raise AuthorityError("daemon time must be UTC")
    return parsed


def validate_resource_policy(value: Any) -> dict[str, Any]:
    """Validate the owner-late-bound, outcome-blind Wave-1 resource policy.

    Amendment D defines ``wall_time_expiry`` as a cumulative active-attempt
    duration in integer seconds.  It is deliberately distinct from the
    security credential's absolute ``expires_at`` timestamp.  The owner
    chooses the integer after the sealed synthetic benchmark and before the
    first P3 real-label access; this function never supplies a default.
    """
    if not isinstance(value, dict) or set(value) != RESOURCE_POLICY_KEYS:
        raise AuthorityError("RESOURCE_POLICY_EXACT_FIELDS_REQUIRED")
    if value["policy_type"] != RESOURCE_POLICY_TYPE:
        raise AuthorityError("RESOURCE_POLICY_TYPE_INVALID")
    seconds = value["wall_time_expiry_seconds"]
    if isinstance(seconds, bool) or not isinstance(seconds, int) or seconds <= 0:
        raise AuthorityError("RESOURCE_POLICY_SECONDS_INVALID")
    expected = {
        "clock": "DAEMON_MONOTONIC_ACTIVE_ATTEMPT_TIME",
        "starts_at": "WAVE1_APPLIED",
        "accumulation": "SUM_ALL_ATTEMPTS_SAME_LOGICAL_WAVE",
        "checkpoint_semantics": "SEALED_PARTIAL_CHECKPOINT_RESUME_ONLY",
        "on_exhaustion": "RESOURCE_EXHAUSTED_OWNER_ACTION_REQUIRED",
        "scientific_early_stop": False,
        "candidate_count": 174,
    }
    if any(value.get(key) != wanted for key, wanted in expected.items()):
        raise AuthorityError("RESOURCE_POLICY_SEMANTICS_INVALID")
    basis = value.get("decision_basis")
    if not isinstance(basis, dict) or set(basis) != RESOURCE_DECISION_BASIS_KEYS:
        raise AuthorityError("RESOURCE_POLICY_DECISION_BASIS_INVALID")
    if basis.get("source") != "SEALED_SYNTHETIC_FULL_PATH_BENCHMARK_ONLY":
        raise AuthorityError("RESOURCE_POLICY_OUTCOME_DERIVED")
    if basis.get("real_p5_labels_read_before_choice") is not False:
        raise AuthorityError("RESOURCE_POLICY_OUTCOME_DERIVED")
    digest = basis.get("benchmark_sha256")
    if not isinstance(digest, str) or len(digest) != 64 or any(
            c not in "0123456789abcdef" for c in digest):
        raise AuthorityError("RESOURCE_POLICY_BENCHMARK_HASH_INVALID")
    return value

def resource_policy_sha256(value: Any) -> str:
    validate_resource_policy(value)
    return sha256(canonical_json(value))


@dataclass(frozen=True)
class FrozenBindings:
    family_id: str
    run_id: str
    run_class: str
    evidence_domain: str
    prereg_sha256: str
    dataset_manifest_sha256: str
    revision_lineage_sha256: str
    universe_rule_sha256: str
    validation_contract_sha256: str
    cost_contract: str
    evaluator_sha256: str
    cutoff: str
    wave_id: str | None = None
    candidate_grammar_sha256: str | None = None
    candidate_list_sha256: str | None = None
    candidate_count: int | None = None
    enumerator_sha256: str | None = None
    evaluation_order_sha256: str | None = None
    executable_contract_sha256: str | None = None
    risc_rule: str | None = None
    resource_scope: dict[str, Any] | None = None

    def validate(self) -> "FrozenBindings":
        if self.run_class not in RUN_CLASSES:
            raise AuthorityError("unsupported run_class")
        for name, value in vars(self).items():
            if name.endswith("sha256") and value is not None:
                if len(value) != 64 or any(c not in "0123456789abcdef" for c in value):
                    raise AuthorityError(f"invalid {name}")
        if self.wave_id is not None:
            required = (self.wave_id, self.candidate_grammar_sha256,
                        self.candidate_list_sha256, self.enumerator_sha256,
                        self.evaluation_order_sha256,
                        self.executable_contract_sha256, self.risc_rule,
                        self.resource_scope)
            if any(value is None for value in required) or self.candidate_count != 174:
                raise AuthorityError("Wave-1 bindings incomplete")
            validate_resource_policy(self.resource_scope)
        elif self.resource_scope is not None:
            raise AuthorityError("RESOURCE_POLICY_ONLY_ALLOWED_FOR_WAVE1")
        return self

    @property
    def digest(self) -> str:
        self.validate()
        return sha256(canonical_json(vars(self)))


@dataclass(frozen=True)
class DaemonContext:
    peer_uid: int
    session_id: str
    recorded_at: str
    ledger_sequence: int

    def validate(self) -> "DaemonContext":
        if type(self.peer_uid) is not int or self.peer_uid < 0:
            raise AuthorityError("invalid daemon peer uid")
        if not self.session_id or type(self.ledger_sequence) is not int:
            raise AuthorityError("daemon session/order missing")
        parse_utc(self.recorded_at)
        return self


@dataclass
class AuthorityProposal:
    proposal_id: str
    bindings: FrozenBindings
    producer_session_id: str
    expires_at: str
    state: str = "PROPOSED"
    events: list[dict[str, Any]] = field(default_factory=list)
    applied_grant_id: str | None = None


class AuthorityFSM:
    """Fail-closed FSM whose trust inputs come only from the daemon."""

    def __init__(self, owner_peer_uid: int,
                 daemon_context: Callable[[], DaemonContext]):
        self._owner_peer_uid = owner_peer_uid
        self._daemon_context = daemon_context

    def _ctx(self) -> DaemonContext:
        return self._daemon_context().validate()

    def _append(self, proposal: AuthorityProposal, target: str,
                details: dict[str, Any]) -> None:
        current_index = STATES.index(proposal.state)
        if current_index + 1 >= len(STATES) or STATES[current_index + 1] != target:
            raise AuthorityError(f"illegal transition {proposal.state}->{target}")
        ctx = self._ctx()
        if proposal.events and ctx.ledger_sequence <= proposal.events[-1]["ledger_sequence"]:
            raise AuthorityError("daemon ledger order is not append-only")
        proposal.events.append({
            "from": proposal.state, "to": target,
            "daemon_recorded_at": ctx.recorded_at,
            "ledger_sequence": ctx.ledger_sequence,
            "immutable_session_id": ctx.session_id,
            "peer_uid": ctx.peer_uid,
            "details": details,
        })
        proposal.state = target

    def preconditions_pass(self, proposal: AuthorityProposal,
                           observed_binding_digest: str) -> None:
        if observed_binding_digest != proposal.bindings.digest:
            raise BindingMismatch("precondition binding digest mismatch")
        self._append(proposal, "PRECONDITIONS_PASS",
                     {"binding_digest": observed_binding_digest})

    def human_owner_sign(self, proposal: AuthorityProposal) -> None:
        ctx = self._ctx()
        if ctx.peer_uid != self._owner_peer_uid:
            raise AuthorizationDenied("HUMAN_OWNER_SIGNED requires owner daemon credential")
        if ctx.session_id == proposal.producer_session_id:
            raise AuthorizationDenied("owner session must differ from producer session")
        self._append(proposal, "HUMAN_OWNER_SIGNED",
                     {"owner_peer_uid": ctx.peer_uid})

    def apply(self, proposal: AuthorityProposal) -> str:
        ctx = self._ctx()
        if parse_utc(ctx.recorded_at) >= parse_utc(proposal.expires_at):
            raise AuthorizationDenied("grant expired under daemon-authoritative time")
        grant_id = "grant-" + sha256(canonical_json({
            "proposal_id": proposal.proposal_id,
            "binding_digest": proposal.bindings.digest,
            "owner_session": ctx.session_id,
        }))[:32]
        self._append(proposal, "APPLIED", {"grant_id": grant_id})
        proposal.applied_grant_id = grant_id
        return grant_id


@dataclass
class Attempt:
    attempt_id: str
    logical_trial_id: str
    ordinal: int
    state: str = "RUNNING"


class TrialRegistry:
    """One logical wave per grant; infrastructure retries keep its identity."""

    def __init__(self) -> None:
        self._logical_by_grant: dict[str, tuple[str, str]] = {}
        self._attempts: dict[str, list[Attempt]] = {}

    def open_wave(self, grant_id: str, candidate_list_sha256: str) -> Attempt:
        existing = self._logical_by_grant.get(grant_id)
        if existing is None:
            logical = "logical-" + sha256(canonical_json(
                {"grant_id": grant_id, "candidate_list_sha256": candidate_list_sha256}))[:32]
            self._logical_by_grant[grant_id] = (logical, candidate_list_sha256)
            self._attempts[logical] = []
        else:
            logical, frozen_hash = existing
            if frozen_hash != candidate_list_sha256:
                raise BindingMismatch("new candidate list requires a new grant/wave")
        ordinal = len(self._attempts[logical]) + 1
        attempt = Attempt(f"{logical}-attempt-{ordinal:04d}", logical, ordinal)
        self._attempts[logical].append(attempt)
        return attempt

    def void_attempt(self, attempt: Attempt) -> None:
        if attempt.state != "RUNNING":
            raise AuthorityError("only running attempt can be voided")
        attempt.state = "ATTEMPT_VOID"

    def complete(self, attempt: Attempt) -> None:
        if attempt.state != "RUNNING":
            raise AuthorityError("only running attempt can complete")
        if any(a.state == "COMPLETED" for a in self._attempts[attempt.logical_trial_id]):
            raise AuthorityError("duplicate logical result")
        attempt.state = "COMPLETED"

    @property
    def logical_trial_count(self) -> int:
        return len(self._logical_by_grant)

#!/usr/bin/env python3
"""Synthetic parser and wire-format tests for researchctl amendment commands.

Covers:
  * direct-owner C/D  -> ``amendment-register-direct`` (choices C|D,
    required --amendment-sha256 and --producer-session-id);
  * delegated A/B     -> ``amendment-register`` (choices A|B only, C/D must
    be rejected by argparse);
  * the JSON request built by ``daemon_request`` (transport-only flags
    --root/--socket/--direct must be stripped, payload must be exact);
  * offline ``--direct`` fail-closed behavior (exit 70, no DB writes).

Nothing here starts researchctld and nothing opens a database: the Unix
socket is faked and every CLI invocation uses a throwaway ``--root`` whose
directory is asserted to stay empty.
"""

from __future__ import annotations

import io
import json
import sys
import tempfile
from contextlib import redirect_stderr, redirect_stdout
from pathlib import Path
from typing import Any, Callable

import synthetic_harness as harness

harness.install()

from app_v2.p5_infra import researchctl  # noqa: E402
from app_v2.p5_infra.authority_store import (  # noqa: E402
    AMENDMENT_A_SHA256,
    AMENDMENT_B_SHA256,
    AMENDMENT_C_SHA256,
)
from app_v2.p5_infra.research_db import FailClosed  # noqa: E402

D_HASH = "d" * 64  # parser-level tests never validate hashes against pins

PASSED: list[str] = []
