class FakeDB:
    instances: list["FakeDB"] = []
    fail_schema: Exception | None = None

    def __init__(self, root: str | Path) -> None:
        self.root = Path(root)
        self.schema_checks = 0
        FakeDB.instances.append(self)

    def schema_version(self) -> int:
        self.schema_checks += 1
