class FakeAuthority:
    instances: list["FakeAuthority"] = []
    behavior: dict[str, Exception] = {}

    def __init__(self, db_path: str | Path) -> None:
        self.db_path = Path(db_path)
        self.calls: list[tuple[Any, ...]] = []
        FakeAuthority.instances.append(self)

    def _record(self, name: str, *args: Any) -> dict[str, Any]:
        self.calls.append((name,) + args)
        if name in FakeAuthority.behavior:
            raise FakeAuthority.behavior[name]
        return {"status": "PASS", "command": name}

    def register_amendment_direct(
        self, amendment_id: str, amendment_sha256: str,
        producer_session_id: str, ctx: Ctx | None,
    ) -> dict[str, Any]:
        return self._record(
